import SwiftUI
import SyncSpaceKit

struct MacTransfersView: View { @EnvironmentObject private var state: SyncSpaceAppState; var body: some View { VStack(alignment: .leading) { Text("Transfers").font(.largeTitle.bold()).padding([.top, .horizontal]); Table(state.transferManager.transfers) { TableColumn("File") { Text($0.fileName) }; TableColumn("Device") { Text($0.deviceName ?? "Unknown") }; TableColumn("Direction") { Text($0.direction.rawValue.capitalized) }; TableColumn("Size") { Text(ByteCountFormatter.string(fromByteCount: $0.fileSize, countStyle: .file)) }; TableColumn("Progress") { ProgressView(value: $0.progress).frame(minWidth: 100) }; TableColumn("Speed") { Text(ByteCountFormatter.string(fromByteCount: Int64($0.transferSpeed), countStyle: .file) + "/s") }; TableColumn("Status") { Text($0.status.rawValue) } }.overlay { if state.transferManager.transfers.isEmpty { ContentUnavailableView("No transfers", systemImage: "arrow.left.arrow.right") } } } } }
struct MacClipboardView: View { @EnvironmentObject private var state: SyncSpaceAppState; @State private var text = ""; @State private var target: Device.ID?; var body: some View { VStack(alignment: .leading, spacing: 16) { Text("Clipboard").font(.largeTitle.bold()); Text("Clipboard sharing is deliberately user-triggered.").foregroundStyle(.secondary); TextEditor(text: $text).font(.body.monospaced()).frame(minHeight: 220).overlay { RoundedRectangle(cornerRadius: 8).stroke(.separator) }; HStack { Button("Read Current Clipboard", systemImage: "doc.on.clipboard") {}.disabled(true); Picker("Device", selection: $target) { Text("Choose a trusted device").tag(Device.ID?.none); ForEach(state.discoveredDevices.filter(\.isTrusted)) { Text($0.name).tag(Device.ID?.some($0.id)) } }.frame(maxWidth: 260); Button("Send", systemImage: "paperplane.fill") {}.buttonStyle(.borderedProminent).disabled(text.isEmpty || target == nil) }; GroupBox("Recent received items") { ContentUnavailableView("No received clipboard items", systemImage: "clipboard") } }.padding(28) } }
